incorrect_example.code:
function deposit() external {
    uint256 amount = msg.value;
    // Vulnerable: assumes WETH transfer equals msg.value, no fee-on-transfer check
    IERC20(weth).safeTransferFrom(msg.sender, address(this), amount);
    shares[msg.sender] += amount; // accounting error if fee-on-transfer
    totalShares += amount;
}

correct_example.code:
function deposit() external {
    uint256 amount = msg.value;
    uint256 balBefore = IERC20(weth).balanceOf(address(this));
    IERC20(weth).safeTransferFrom(msg.sender, address(this), amount);
    uint256 balAfter = IERC20(weth).balanceOf(address(this));
    uint256 received = balAfter - balBefore;
    shares[msg.sender] += received;
    totalShares += received;
}
